begin;
select plan(12);
insert into auth.users(id,email) values ('90000000-0000-0000-0000-000000000001','transfer-admin@example.test'),('90000000-0000-0000-0000-000000000002','transfer-worker@example.test'),('90000000-0000-0000-0000-000000000003','transfer-other@example.test');
insert into public.profiles(id,display_name,role,active) values ('90000000-0000-0000-0000-000000000001','Admin','admin',true),('90000000-0000-0000-0000-000000000002','Worker','collaborator',true),('90000000-0000-0000-0000-000000000003','Other','collaborator',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select public.create_material('Transfer test','g',0);
select public.adjust_warehouse_stock('90000000-0000-0000-0000-000000000004',(select id from public.materials where name='Transfer test'),10,'initial');
select lives_ok($$select public.dispatch_stock('90000000-0000-0000-0000-000000000005','90000000-0000-0000-0000-000000000002',(select id from public.materials where name='Transfer test'),4,'')$$,'admin dispatches');
select lives_ok($$select public.dispatch_stock('90000000-0000-0000-0000-000000000005','90000000-0000-0000-0000-000000000002',(select id from public.materials where name='Transfer test'),4,'')$$,'retry dispatch');
select is((select quantity from public.warehouse_balances where material_id=(select id from public.materials where name='Transfer test')),6::numeric,'warehouse reduced once');
select is((select sum(quantity) from public.stock_transfers where received_at is null),4::numeric,'stock is in transit');
select throws_ok($$select public.dispatch_stock('90000000-0000-0000-0000-000000000006','90000000-0000-0000-0000-000000000002',(select id from public.materials where name='Transfer test'),7,'')$$,'P0001','insufficient stock','cannot dispatch unavailable stock');
select is((select count(*) from public.stock_transfers),1::bigint,'failed dispatch is rolled back');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000003',true);
select is((select count(*) from public.stock_transfers),0::bigint,'other collaborator cannot read transfer');
select throws_ok($$select public.confirm_stock_receipt((select id from public.stock_transfers limit 1))$$,'42501','transfer not found','other collaborator cannot confirm');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select lives_ok($$select public.confirm_stock_receipt((select id from public.stock_transfers limit 1))$$,'recipient confirms');
select lives_ok($$select public.confirm_stock_receipt((select id from public.stock_transfers limit 1))$$,'retry confirmation');
select is((select quantity from public.custody_balances),4::numeric,'custody credited once');
select throws_ok($$update public.custody_balances set quantity=100$$,'42501',null,'direct custody writes denied');
select * from finish();
rollback;
